        write(CYN "赫尔苏诧异地说道：你给我这个干什么？\n" NOR);
        return 0;
    }

    if (query("count") < 1) {
        write(CYN "赫尔苏摇头道：你等下次吧，现在我手里也没货。\n" NOR);
        return 0;
    }

    if (!who->query_temp("tmark/参")) {
        write(CYN "赫尔苏疑惑道：我又不是乞丐，没事给我钱作甚？\n" NOR);
        return 0;
    }

    if (ob->value() < 100000) {
        write(CYN "赫尔苏冷笑道：嘿嘿，给我这么多钱哪？\n" NOR);
        return 0;
