    );


    set("gender", "男性");
    set("attitude", "friendly");
    set("class", "bonze");

    set("age", 40);
    set("shen_type", 1);
    set("str", 20);
    set("int", 20);
    set("con", 20);
    set("dex", 20);
    set("max_qi", 400);
    set("max_jing", 300);
    set("neili", 450);
    set("max_neili", 450);
    set("jiali", 40);
    set("combat_exp", 10000);
    set("score", 100);

    set_skill("force", 50);
    set_skill("hunyuan-yiqi", 50);
    set_skill("shaolin-xinfa", 50);
    set_skill("dodge", 50);
    set_skill("shaolin-shenfa", 50);
    set_skill("strike", 50);
    set_skill("banruo-zhang", 50);
    set_skill("parry", 50);
    set_skill("damo-jian", 50);
    set_skill("buddhism", 50);
    set_skill("literate", 50);

    map_skill("force", "hunyuan-yiqi");
    map_skill("dodge", "shaolin-shenfa");
    map_skill("strike", "banruo-zhang");
    map_skill("parry", "damo-jian");

    prepare_skill("strike", "banruo-zhang");

    create_family("少林派", 39, "弟子");

    set("inquiry", ([
        "齐眉棍": (: ask_me, "qimeigun" :),
        "戒刀": (: ask_me, "jiedao" :),
        "禅杖": (: ask_me, "chanzhang" :),
        "长剑": (: ask_me, "changjian" :),
        "皮鞭": (: ask_me, "changbian" :),
    ]));

    set("wuqi_count", 15);

    setup();

    carry_object("/d/items/cloth/hui_jiasha")->wear();
}

string ask_me(string name) {
    mapping fam;
    object ob;

    if (!(fam = this_player()->query("family")) || fam["family_name"] != "少林派")
        return RANK_D->query_respect(this_player()) + "与本派素无来往，不知此话从何谈起？";

    if (present(name, this_player()))
        return RANK_D->query_respect(this_player()) + "你现在身上不是有这样武器吗，怎麽又来要了？ 真是贪得无餍！";

    if (query("wuqi_count") < 1)
        return "抱歉，你来得不是时候，武器已经发完了。";

    if (name == "changjian")
        ob = new("/d/items/sword/changjian5");
    else if (name == "jiedao")
        ob = new("/d/items/blade/jiedao2");
    else
        ob = new("/d/shaolin/obj/" + name);
    ob->move(this_player());

    add("wuqi_count", -1);

    message_vision("道尘给$N一件" + ob->query("name") + "。\n", this_player());

    return "拿去吧。不过要记住，武器只可防身练武，不可凭此杀害生灵。";
}

